-- Location reference hierarchy for water-quality reports
-- Tehsil → Village → Settlement

CREATE TABLE "tehsils" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "tehsils_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "tehsils_name_key" ON "tehsils"("name");

CREATE TABLE "villages" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "tehsil_id" TEXT NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "villages_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "villages_tehsil_id_idx" ON "villages"("tehsil_id");
CREATE INDEX "villages_name_idx" ON "villages"("name");
CREATE UNIQUE INDEX "villages_tehsil_id_name_key" ON "villages"("tehsil_id", "name");

ALTER TABLE "villages"
  ADD CONSTRAINT "villages_tehsil_id_fkey"
  FOREIGN KEY ("tehsil_id") REFERENCES "tehsils"("id")
  ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "settlements" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "village_id" TEXT NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "settlements_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "settlements_village_id_idx" ON "settlements"("village_id");
CREATE INDEX "settlements_name_idx" ON "settlements"("name");
CREATE UNIQUE INDEX "settlements_village_id_name_key" ON "settlements"("village_id", "name");

ALTER TABLE "settlements"
  ADD CONSTRAINT "settlements_village_id_fkey"
  FOREIGN KEY ("village_id") REFERENCES "villages"("id")
  ON DELETE CASCADE ON UPDATE CASCADE;

